SECRET=SECRET_LAT+[['拉丁名词 sēcrētum；古法语形容词 secret','秘密；不公开的，分别传入英语'],['中古英语 secret / secrette → 英语 secret','秘密；秘密的']]
SECRETARY=SECRET_LAT+[['中古拉丁语：sēcrētārius','被托付私人或机密事务的人'],['中古英语 secretarie → 英语 secretary','处理文书、联络事务的人；某些机构的主管头衔']]
SECRETION=SECERN+[['拉丁语：sēcrētiō','分开、分离'],['法语 sécrétion → 英语 secretion','生理学中的分泌；分泌物']]
EXCERN=C+[['拉丁语：ex- + cernere → excernere；分词 excrētus','向外筛出、排出']]
EXCRETE=EXCERN+[['英语：excrete','排出体外；排泄']]
CONCERN=C+[['后期拉丁语：con- + cernere → concernere','一起筛、混合'],['中古拉丁语 concernere → 法语 concerner','涉及、与某事有关'],['中古英语及现代英语：concern','涉及 → 影响、使担心；后来也作名词']]
DECRETUM=C+[['拉丁语：dē- + cernere → dēcernere','判定、作出决定'],['拉丁语：dēcrētum','已作出的决定、命令']]
DECREE=DECRETUM+[['古法语 decre / decret → 中古英语 decre','正式法令、裁决'],['英语：decree','法令；名词又转为动词“颁令、裁定”']]
CONCERT_IT=[['意大利语：concertare','协调、商定；更早与拉丁“争论”等形式的关系有争议']]
CONCERT=CONCERT_IT+[['意大利语 concerto → 法语 concert','协调、合奏'],['英语：concert（名词）','一致、协同；音乐会']]
CONCERT_V=CONCERT_IT+[['法语 concerter → 英语 concert（动词）','共同商定、协调安排']]
DISCONCERT=CONCERT_IT+[['法语：concerter → disconcerter','协调安排 → 打乱协调、使困惑'],['英语：disconcert','扰乱镇定；使不知所措']]
def D(h,w,m):return h+[['英语：'+w,m]]
